    def _read_csv_tail_for_bot(self, path: str, max_lines: int = 50000) -> pd.DataFrame:
        try:
            if not os.path.exists(path) or os.path.getsize(path) == 0:
                return pd.DataFrame()
            with open(path, "r", encoding="utf-8", errors="replace", newline="") as f:
                header = f.readline()
                rows = deque(f, maxlen=max(1, int(max_lines)))
            if not header:
                return pd.DataFrame()
            return pd.read_csv(StringIO(header + "".join(rows)))
        except Exception as exc:
            module_exception(MODULE_NAME, "bot_csv_tail_read_failed", exc, data={"path": path, "max_lines": max_lines, "traceback": traceback.format_exc()}, also_overall=False)
            return pd.DataFrame()

    def _micro_candles_for_replay_window(self, *, product_id: str, start_ts: float, end_ts: float) -> pd.DataFrame:
        try:
            live_series = self.live_1m.get(product_id)
            if live_series is not None and getattr(live_series, "candles", None):
                rows = []
                for c in list(live_series.candles):
                    ts_val = float(getattr(c, "ts", 0.0))
                    if float(start_ts) <= ts_val <= float(end_ts):
                        rows.append({"ts": ts_val, "open": float(getattr(c, "open", 0.0)), "high": float(getattr(c, "high", 0.0)), "low": float(getattr(c, "low", 0.0)), "close": float(getattr(c, "close", 0.0)), "volume": float(getattr(c, "volume", 0.0) or 0.0)})
                if rows:
                    return pd.DataFrame(rows).sort_values("ts")
            for path in [MICRO_HISTORY_CSV_PATH, CHART_1M_7D_CSV_PATH, HIST_REPLAY_15M_90D_CSV_PATH]:
                try:
                    frame = self._read_csv_tail_for_bot(path, max_lines=150000)
                    if frame.empty or "product_id" not in frame.columns:
                        continue
                    frame = frame[frame["product_id"].astype(str).eq(str(product_id))].copy()
                    if frame.empty:
                        continue
                    frame["ts"] = pd.to_numeric(frame.get("ts"), errors="coerce")
                    frame = frame.dropna(subset=["ts"])
                    frame = frame[(frame["ts"] >= float(start_ts)) & (frame["ts"] <= float(end_ts))].copy()
                    for col in ["open", "high", "low", "close", "volume"]:
                        if col in frame.columns:
                            frame[col] = pd.to_numeric(frame.get(col), errors="coerce")
                    frame = frame.dropna(subset=["open", "high", "low", "close"]).sort_values("ts")
                    if not frame.empty:
                        module_debug(MODULE_NAME, "runtime_shadow_replay_candles_loaded", data={"product_id": product_id, "path": path, "rows": len(frame), "start_ts": start_ts, "end_ts": end_ts}, level="DEBUG", also_overall=False)
                        return frame
                except Exception as exc:
                    module_exception(MODULE_NAME, "runtime_shadow_replay_candle_source_failed", exc, data={"product_id": product_id, "path": path, "start_ts": start_ts, "end_ts": end_ts, "traceback": traceback.format_exc()}, also_overall=False)
            return pd.DataFrame()
        except Exception as exc:
            module_exception(MODULE_NAME, "micro_candles_for_replay_window_failed", exc, data={"product_id": product_id, "start_ts": start_ts, "end_ts": end_ts, "traceback": traceback.format_exc()}, also_overall=False)
            return pd.DataFrame()

    def _runtime_shadow_decisions_for_sell_replay(self) -> pd.DataFrame:
        frames = []
        try:
            decisions = self._read_csv_tail_for_bot(LEVEL8_COUNCIL_DECISIONS_CSV_PATH, max_lines=30000)
            if not decisions.empty and {"ts", "decision_id", "product_id", "action"}.issubset(set(decisions.columns)):
                decisions = decisions.copy()
                decisions["source_file"] = "council_decisions.csv"
                frames.append(decisions)
        except Exception:
            pass
        try:
            shadows = self._read_csv_tail_for_bot(SHADOW_TRADES_CSV_PATH, max_lines=30000)
            if not shadows.empty and {"ts", "decision_id", "product_id"}.issubset(set(shadows.columns)):
                shadows = shadows.copy()
                shadow_action = shadows.get("shadow_action", pd.Series("BUY", index=shadows.index)).astype(str).str.upper()
                shadows["action"] = shadow_action.apply(lambda x: "SHADOW_BUY" if x == "BUY" else f"SHADOW_{x}")
                shadows["decision_bucket"] = "SHADOW"
                shadows["source_file"] = "shadow_trades.csv"
                frames.append(shadows)
        except Exception:
            pass
        if not frames:
            return pd.DataFrame()
        out = pd.concat(frames, ignore_index=True, sort=False)
        out["ts"] = pd.to_numeric(out.get("ts"), errors="coerce")
        out = out.dropna(subset=["ts"])
        if "decision_id" in out.columns:
            out = out.drop_duplicates(subset=["decision_id"], keep="last")
        return out.sort_values("ts")

    def _simulate_shadow_sell_for_decision(self, *, decision_row: Dict[str, Any], candles: pd.DataFrame) -> Optional[Dict[str, Any]]:
        try:
            product_id = str(decision_row.get("product_id") or "")
            decision_id = str(decision_row.get("decision_id") or "")
            decision_ts = float(decision_row.get("ts") or 0.0)
            if not product_id or not decision_id or decision_ts <= 0 or candles.empty:
                return None
            entry_price = self._market_price_near_ts(product_id=product_id, target_ts=decision_ts, max_age_sec=180.0)
            if entry_price is None or float(entry_price) <= 0:
                first = candles.iloc[0].to_dict()
                entry_price = float(first.get("open") or first.get("close") or 0.0)
            if not entry_price or float(entry_price) <= 0:
                return None
            entry_fee_bps = float(self._entry_fee_bps_for_mode(execution_mode=ENTRY_EXECUTION_MODE))
            exit_fee_bps = float(self._exit_fee_bps_for_mode())
            synthetic_notional = float(SHADOW_SELL_REPLAY_SYNTHETIC_NOTIONAL_USD)
            entry_fee_usd = fee_usd(synthetic_notional, entry_fee_bps)
            synthetic_qty = synthetic_notional / float(entry_price)
            all_in_entry_price = (synthetic_notional + entry_fee_usd) / max(synthetic_qty, 1e-12)
            min_profitable_exit_price = float(required_exit_price_for_net_gain(effective_entry_price=float(all_in_entry_price), exit_fee_bps=float(exit_fee_bps), est_slippage_bps=EST_SLIPPAGE_BPS, est_adverse_fill_bps=EST_ADVERSE_FILL_BPS, min_net_gain_bps=max(MIN_NET_PROFIT_BPS_FOR_DISCRETIONARY_EXIT, MIN_NET_GAIN_AFTER_FEES_BPS)))
            hard_stop_price = float(all_in_entry_price) * (1.0 - float(MAX_POSITION_LOSS_BEFORE_FORCED_SELL_PCT))
            profile = self.calibration_profiles.get(product_id, ProductCalibrationProfile(product_id=product_id))
            scalp_pullback_pct = float(getattr(profile, "scalp_pullback_pct", 0.0025) or 0.0025)
            max_hold_sec = float(LEVEL8_MAX_HOLD_SEC)
            min_hold_sec = float(LEVEL8_MIN_HOLD_SEC)
            peak_price = float(entry_price); trough_price = float(entry_price); profit_armed = False
            exit_ts = None; exit_price = None; exit_reason = ""
            for _, candle in candles.iterrows():
                ts_val = float(candle.get("ts") or 0.0)
                if ts_val < decision_ts:
                    continue
                age_sec = ts_val - decision_ts
                high = float(candle.get("high") or 0.0); low = float(candle.get("low") or 0.0); close = float(candle.get("close") or 0.0)
                if high > 0: peak_price = max(peak_price, high)
                if low > 0: trough_price = min(trough_price, low)
                if low > 0 and low <= hard_stop_price:
                    exit_ts = ts_val; exit_price = hard_stop_price; exit_reason = "shadow_hard_stop"; break
                if age_sec >= min_hold_sec and high >= min_profitable_exit_price:
                    profit_armed = True
                if profit_armed:
                    pullback_trigger = float(peak_price) * (1.0 - float(scalp_pullback_pct))
                    if close > 0 and close <= pullback_trigger:
                        exit_ts = ts_val; exit_price = close; exit_reason = "shadow_profit_pullback"; break
                if age_sec >= max_hold_sec:
                    exit_ts = ts_val; exit_price = close if close > 0 else peak_price; exit_reason = "shadow_max_hold_exit"; break
            if exit_ts is None:
                last = candles.iloc[-1].to_dict()
                exit_ts = float(last.get("ts") or decision_ts); exit_price = float(last.get("close") or entry_price); exit_reason = "shadow_latest_available_exit"
            gross_proceeds = synthetic_qty * float(exit_price)
            exit_fee = fee_usd(gross_proceeds, exit_fee_bps)
            net_pnl = gross_proceeds - synthetic_notional - entry_fee_usd - exit_fee
            gross_pnl = gross_proceeds - synthetic_notional
            net_pnl_bps = (net_pnl / max(synthetic_notional, 1e-12)) * 10000.0
            max_favorable_bps = ((peak_price / float(entry_price)) - 1.0) * 10000.0
            max_adverse_bps = ((trough_price / float(entry_price)) - 1.0) * 10000.0
            return {"ts": now_ts(), "dt_mst": datetime.fromtimestamp(now_ts(), tz=timezone.utc).astimezone(TZ).strftime("%Y-%m-%d %H:%M:%S"), "replay_key": f"{decision_id}|{int(SHADOW_SELL_REPLAY_MAX_REVIEW_MINUTES)}", "decision_id": decision_id, "product_id": product_id, "decision_ts": decision_ts, "entry_price": float(entry_price), "entry_fee_bps": entry_fee_bps, "exit_fee_bps": exit_fee_bps, "synthetic_notional_usd": synthetic_notional, "synthetic_qty": synthetic_qty, "all_in_entry_price": all_in_entry_price, "min_profitable_exit_price": min_profitable_exit_price, "hard_stop_price": hard_stop_price, "exit_ts": float(exit_ts), "exit_price": float(exit_price), "exit_reason": exit_reason, "held_seconds": max(0.0, float(exit_ts) - float(decision_ts)), "max_favorable_bps": max_favorable_bps, "max_adverse_bps": max_adverse_bps, "peak_price": peak_price, "trough_price": trough_price, "gross_pnl_usd": gross_pnl, "exit_fee_usd": exit_fee, "net_pnl_usd": net_pnl, "net_pnl_bps": net_pnl_bps, "would_have_won": int(net_pnl > 0), "would_have_hit_stop": int(exit_reason == "shadow_hard_stop"), "would_have_hit_min_profit": int(peak_price >= min_profitable_exit_price), "decision_action": str(decision_row.get("action") or ""), "decision_bucket": str(decision_row.get("bucket") or ""), "decision_strategy": str(decision_row.get("strategy") or ""), "final_buy_score": float(decision_row.get("final_buy_score") or 0.0), "buy_threshold": float(decision_row.get("buy_threshold") or 0.0), "truth_score": float(decision_row.get("truth_score") or 0.0), "recommended_position_pct": float(decision_row.get("recommended_position_pct") or 0.0), "reason": f"shadow_sell_replay;exit={exit_reason};net_bps={net_pnl_bps:.2f};mfe={max_favorable_bps:.2f};mae={max_adverse_bps:.2f};min_profit_px={min_profitable_exit_price:.8f}"}
        except Exception as exc:
            module_exception(MODULE_NAME, "simulate_shadow_sell_for_decision_failed", exc, data={"decision_id": decision_row.get("decision_id", ""), "product_id": decision_row.get("product_id", ""), "traceback": traceback.format_exc()}, also_overall=False)
            return None

    def _review_shadow_sell_replay(self) -> None:
        if not bool(ENABLE_SHADOW_SELL_REPLAY):
            return
        now_value = now_ts()
        if now_value - float(getattr(self, "_last_shadow_sell_replay_ts", 0.0) or 0.0) < float(SHADOW_SELL_REPLAY_EVERY_SEC):
            return
        self._last_shadow_sell_replay_ts = now_value
        self._ensure_shadow_sell_replay_header()
        try:
            decisions = self._runtime_shadow_decisions_for_sell_replay()
            if decisions.empty:
                module_debug(MODULE_NAME, "shadow_sell_replay_no_rows", data={"source_rows": 0, "reviewable": 0, "skip_counts": {}, "action_counts": {}, "now_ts": now_value, "min_age_sec": float(SHADOW_SELL_REPLAY_MIN_REVIEW_MINUTES) * 60.0, "max_age_sec": float(SHADOW_SELL_REPLAY_MAX_REVIEW_MINUTES) * 60.0}, level="INFO", also_overall=False)
                return
            decisions["ts"] = pd.to_numeric(decisions["ts"], errors="coerce")
            decisions = decisions.dropna(subset=["ts"])
            min_age_sec = float(SHADOW_SELL_REPLAY_MIN_REVIEW_MINUTES) * 60.0
            max_age_sec = float(SHADOW_SELL_REPLAY_MAX_REVIEW_MINUTES) * 60.0
            reviewable_actions = {"SHADOW", "SHADOW_BUY", "BUY", "COMMENTARY", "WAIT"}
            reviewable = decisions[(decisions["ts"] <= now_value - min_age_sec) & (decisions["ts"] >= now_value - max_age_sec) & (decisions["action"].astype(str).str.upper().isin(reviewable_actions))].copy()
            if reviewable.empty:
                action_counts = (decisions["action"].astype(str).str.upper().value_counts().to_dict() if "action" in decisions.columns else {})
                module_debug(MODULE_NAME, "shadow_sell_replay_no_rows", data={"source_rows": int(len(decisions)), "reviewable": 0, "action_counts": action_counts, "oldest_ts": float(decisions["ts"].min()) if "ts" in decisions.columns and not decisions.empty else 0.0, "newest_ts": float(decisions["ts"].max()) if "ts" in decisions.columns and not decisions.empty else 0.0, "now_ts": now_value, "min_age_sec": min_age_sec, "max_age_sec": max_age_sec}, level="INFO", also_overall=False)
                return
            existing_keys = set()
            if os.path.exists(SHADOW_SELL_REPLAY_CSV_PATH):
                existing = self._read_csv_tail_for_bot(SHADOW_SELL_REPLAY_CSV_PATH, max_lines=50000)
                if not existing.empty and "replay_key" in existing.columns:
                    existing_keys = set(existing["replay_key"].astype(str).tolist())
            rows_to_write = []
            skip_counts = {"existing_key": 0, "no_decision_id": 0, "no_candles": 0, "simulate_none": 0, "written": 0}
            for _, decision in reviewable.tail(int(SHADOW_SELL_REPLAY_MAX_ROWS_PER_PASS)).iterrows():
                decision_row = decision.to_dict()
                decision_id = str(decision_row.get("decision_id") or "")
                product_id = str(decision_row.get("product_id") or "")
                decision_ts = float(decision_row.get("ts") or 0.0)
                if not decision_id or not product_id or decision_ts <= 0:
                    skip_counts["no_decision_id"] += 1
                    continue
                replay_key = f"{decision_id}|{int(SHADOW_SELL_REPLAY_MAX_REVIEW_MINUTES)}"
                if replay_key in existing_keys:
                    skip_counts["existing_key"] += 1
                    continue
                candles = self._micro_candles_for_replay_window(product_id=product_id, start_ts=decision_ts, end_ts=decision_ts + float(SHADOW_SELL_REPLAY_MAX_REVIEW_MINUTES) * 60.0)
                if candles.empty:
                    skip_counts["no_candles"] += 1
                    continue
                replay_row = self._simulate_shadow_sell_for_decision(decision_row=decision_row, candles=candles)
                if replay_row:
                    rows_to_write.append(replay_row); existing_keys.add(replay_key); skip_counts["written"] += 1
                else:
                    skip_counts["simulate_none"] += 1
            if not rows_to_write:
                module_debug(MODULE_NAME, "shadow_sell_replay_no_rows", data={"source_rows": int(len(decisions)) if decisions is not None else 0, "reviewable": int(len(reviewable)) if "reviewable" in locals() else 0, "skip_counts": skip_counts if "skip_counts" in locals() else {}, "action_counts": (decisions["action"].astype(str).str.upper().value_counts().to_dict() if decisions is not None and not decisions.empty and "action" in decisions.columns else {}), "now_ts": now_value, "min_age_sec": float(SHADOW_SELL_REPLAY_MIN_REVIEW_MINUTES) * 60.0, "max_age_sec": float(SHADOW_SELL_REPLAY_MAX_REVIEW_MINUTES) * 60.0}, level="INFO", also_overall=False)
                return
            with open(SHADOW_SELL_REPLAY_CSV_PATH, "a", newline="", encoding="utf-8") as f:
                writer = csv.DictWriter(f, fieldnames=SHADOW_SELL_REPLAY_COLUMNS)
                for row in rows_to_write:
                    writer.writerow({col: row.get(col, "") for col in SHADOW_SELL_REPLAY_COLUMNS})
            module_debug(MODULE_NAME, "shadow_sell_replay_rows_written", data={"rows": len(rows_to_write), "reviewable": int(len(reviewable))}, level="INFO", also_overall=False)
        except Exception as exc:
            module_exception(MODULE_NAME, "review_shadow_sell_replay_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=True)


    async def _run_historical_shadow_replay_job(
        self,
        *,
        product_id: str,
        timeframe: str,
        write_mode: str = "master",
        output_path: Optional[str] = None,
    ) -> Dict[str, Any]:
        """
        Run one historical replay job for one product/timeframe.
        This worker is safe to run in parallel with other product/timeframe jobs.
        It returns metadata and appends replay rows under a write lock.
        """
        pass_started = time.perf_counter()
        result: Dict[str, Any] = {"product_id": product_id, "timeframe": timeframe, "write_mode": write_mode, "output_path": output_path or "", "ok": False, "rows_written": 0, "evaluated": 0, "error": ""}
        try:
            self._ensure_historical_shadow_replay_header()
            existing_keys = self._historical_replay_existing_keys()
            existing_prefixes = self._historical_replay_existing_prefixes(existing_keys)
            fetch_started = time.perf_counter()
            candles, granularity, replay_source = await self._get_historical_replay_candles(product_id=product_id, timeframe=timeframe)
            fetch_elapsed_sec = time.perf_counter() - fetch_started
            eval_started = time.perf_counter()
            result.update({"granularity": granularity, "source": replay_source, "candles": len(candles), "fetch_elapsed_sec": round(fetch_elapsed_sec, 3)})
            if not candles:
                module_debug(MODULE_NAME, "historical_shadow_replay_no_candles", data={"product_id": product_id, "timeframe": timeframe}, level="INFO", also_overall=False)
                return result
            if timeframe == "primary_15m_90d":
                min_prefix = int(HIST_REPLAY_MIN_PREFIX_15M); forward_windows = list(HIST_REPLAY_FORWARD_BARS_15M); step_bars = int(HIST_REPLAY_STEP_BARS_15M)
            elif timeframe == "regime_1h_365d":
                min_prefix = int(HIST_REPLAY_MIN_PREFIX_1H); forward_windows = list(HIST_REPLAY_FORWARD_BARS_1H); step_bars = int(HIST_REPLAY_STEP_BARS_1H)
            else:
                min_prefix = 60; forward_windows = [5, 10, 20]; step_bars = 10
            max_forward = max(forward_windows)
            rows_to_write: List[Dict[str, Any]] = []
            evaluated = 0
            for i in range(min_prefix, len(candles) - max_forward, max(1, step_bars)):
                if time.perf_counter() - eval_started >= float(HIST_REPLAY_MAX_RUNTIME_SEC):
                    module_debug(MODULE_NAME, "historical_shadow_replay_eval_budget_reached", data={"product_id": product_id, "timeframe": timeframe, "evaluated": evaluated, "rows_to_write": len(rows_to_write), "eval_elapsed_sec": round(time.perf_counter() - eval_started, 3), "fetch_elapsed_sec": round(fetch_elapsed_sec, 3), "budget_sec": float(HIST_REPLAY_MAX_RUNTIME_SEC)}, level="INFO", also_overall=False)
                    break
                if evaluated >= int(HIST_REPLAY_MAX_CANDIDATES_PER_PASS):
                    break
                prefix = candles[:i]
                for forward_bars in forward_windows:
                    future = candles[i:i + int(forward_bars)]
                    if len(future) < int(forward_bars):
                        continue
                    replay_ts = int(prefix[-1].ts)
                    rough_key_prefix = f"{product_id}|{timeframe}|{replay_ts}|"
                    if rough_key_prefix in existing_prefixes:
                        continue
                    row = self._simulate_historical_replay_candidate(product_id=product_id, timeframe=timeframe, granularity=granularity, prefix=prefix, future=future, replay_source=replay_source)
                    evaluated += 1
                    if row:
                        key = str(row.get("replay_key") or "")
                        if key and key not in existing_keys:
                            rows_to_write.append(row)
                            existing_keys.add(key)
                            parts = key.split("|")
                            if len(parts) >= 3:
                                existing_prefixes.add("|".join(parts[:3]) + "|")
                    break
            rows_written = 0
            if rows_to_write:
                if str(write_mode) == "worker_file":
                    final_output_path = output_path or self._worker_output_path_for_job(product_id, timeframe)
                    rows_written = await asyncio.to_thread(self._write_worker_replay_rows, output_path=final_output_path, rows=rows_to_write)
                    result["output_path"] = final_output_path
                else:
                    async with self._historical_replay_output_write_lock:
                        with open(HISTORICAL_SHADOW_REPLAY_CSV_PATH, "a", newline="", encoding="utf-8") as f:
                            writer = csv.DictWriter(f, fieldnames=HISTORICAL_SHADOW_REPLAY_COLUMNS)
                            for row in rows_to_write:
                                writer.writerow({col: row.get(col, "") for col in HISTORICAL_SHADOW_REPLAY_COLUMNS})
                    rows_written = len(rows_to_write)
                try:
                    if str(write_mode) != "worker_file":
                        for row in rows_to_write:
                            key = str(row.get("replay_key") or "")
                            if key:
                                self._historical_replay_existing_keys_cache.add(key)
                    self._historical_replay_counts_cache_ts = 0.0
                    self._calculation_status_cache_ts = 0.0
                except Exception:
                    pass
            async with self._historical_replay_status_write_lock:
                await asyncio.to_thread(self._write_historical_replay_summary, product_id)
            result.update({"ok": True, "evaluated": int(evaluated), "rows_written": int(rows_written), "eval_elapsed_sec": round(time.perf_counter() - eval_started, 3), "total_elapsed_sec": round(time.perf_counter() - pass_started, 3)})
            module_debug(MODULE_NAME, "historical_shadow_replay_job_completed", data=dict(result), level="INFO", also_overall=False)
            return result
        except Exception as exc:
            result["error"] = str(exc)
            module_exception(MODULE_NAME, "historical_shadow_replay_job_failed", exc, data={"product_id": product_id, "timeframe": timeframe, "traceback": traceback.format_exc()}, also_overall=True)
            return result


    async def _run_manifest_job_in_process_worker(self, job: Dict[str, Any]) -> Dict[str, Any]:
        product_id = str(job.get("product_id") or "")
        timeframe = str(job.get("timeframe") or "")
        job_id = str(job.get("job_id") or safe_job_id(product_id, timeframe))
        output_path = str(job.get("output_path") or self._worker_output_path_for_job(product_id, timeframe))
        already_done, already_reason, already_rows = self._job_already_satisfied_in_master(product_id, timeframe)
        if already_done:
            async with self._historical_replay_manifest_lock:
                update_job(
                    path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH,
                    job_id=job_id,
                    updates={
                        "status": JOB_MERGED,
                        "started_ts": now_ts(),
                        "finished_ts": now_ts(),
                        "merged_ts": now_ts(),
                        "rows_written": int(already_rows),
                        "rows_appended_to_master": 0,
                        "merge_note": "already_satisfied_in_master",
                        "worker_mode": "process",
                        "error": "",
                        "source": "master_csv",
                    },
                )
            return {
                "ok": True,
                "worker_mode": "process",
                "product_id": product_id,
                "timeframe": timeframe,
                "rows_written": 0,
                "rows_existing_in_master": int(already_rows),
                "reason": already_reason,
                "already_satisfied_in_master": True,
            }
        async with self._historical_replay_manifest_lock:
            update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates={"status": JOB_RUNNING, "attempts": int(job.get("attempts", 0) or 0) + 1, "started_ts": now_ts(), "error": "", "output_path": output_path, "worker_mode": "process"})
        try:
            cache_ok, source, candle_rows = await self._ensure_replay_candle_cache_for_job(product_id=product_id, timeframe=timeframe)
            if not cache_ok:
                updates = {"status": JOB_FAILED, "finished_ts": now_ts(), "candle_rows": int(candle_rows), "source": source, "error": f"insufficient candle cache rows={candle_rows}"}
                async with self._historical_replay_manifest_lock:
                    update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates=updates)
                return {"ok": False, "worker_mode": "process", "product_id": product_id, "timeframe": timeframe, "error": updates["error"], "candle_rows": int(candle_rows), "source": source}
            if self._historical_worker_pool is None or run_full_replay_worker_job is None:
                raise RuntimeError("Process worker pool or run_full_replay_worker_job unavailable")
            payload = self._build_process_worker_payload({**job, "output_path": output_path})
            loop = asyncio.get_running_loop()
            result = await loop.run_in_executor(self._historical_worker_pool, run_full_replay_worker_job, payload)
            updates = {"finished_ts": now_ts(), "rows_written": int(result.get("rows_written", 0) or 0), "evaluated": int(result.get("evaluated", 0) or 0), "candle_rows": int(result.get("candles", candle_rows) or 0), "qualified_rows": int(result.get("qualified_rows", 0) or 0), "accepted_rows": int(result.get("accepted_rows", 0) or 0), "avg_net_pnl_bps": float(result.get("avg_net_pnl_bps", 0.0) or 0.0), "median_net_pnl_bps": float(result.get("median_net_pnl_bps", 0.0) or 0.0), "source": source, "output_path": output_path, "worker_mode": "process"}
            if bool(result.get("ok")) and int(result.get("rows_written", 0) or 0) > 0:
                updates["status"] = JOB_DONE
                updates["error"] = ""
            elif bool(result.get("ok")):
                already_done, already_reason, already_rows = self._job_already_satisfied_in_master(product_id, timeframe)
                if already_done:
                    updates["status"] = JOB_MERGED
                    updates["merged_ts"] = now_ts()
                    updates["rows_written"] = int(already_rows)
                    updates["rows_appended_to_master"] = 0
                    updates["merge_note"] = "worker_wrote_zero_but_master_satisfied"
                    updates["error"] = ""
                else:
                    updates["status"] = JOB_FAILED
                    updates["error"] = f"process worker wrote zero rows and master not satisfied; {already_reason}"
            else:
                updates["status"] = JOB_FAILED
                updates["error"] = str(result.get("error") or "process worker failed")
            async with self._historical_replay_manifest_lock:
                update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates=updates)
            return result
        except Exception as exc:
            async with self._historical_replay_manifest_lock:
                update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates={"status": JOB_FAILED, "finished_ts": now_ts(), "worker_mode": "process", "error": str(exc)})
            module_exception(MODULE_NAME, "run_manifest_job_in_process_worker_failed", exc, data={"product_id": product_id, "timeframe": timeframe, "job_id": job_id, "traceback": traceback.format_exc()}, also_overall=True)
            return {"ok": False, "worker_mode": "process", "product_id": product_id, "timeframe": timeframe, "error": str(exc)}

    async def _run_manifest_job_to_worker_file(self, job: Dict[str, Any]) -> Dict[str, Any]:
        product_id = str(job.get("product_id") or "")
        timeframe = str(job.get("timeframe") or "")
        job_id = str(job.get("job_id") or safe_job_id(product_id, timeframe))
        output_path = str(job.get("output_path") or self._worker_output_path_for_job(product_id, timeframe))
        async with self._historical_replay_manifest_lock:
            update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates={"status": JOB_RUNNING, "attempts": int(job.get("attempts", 0) or 0) + 1, "started_ts": now_ts(), "error": "", "output_path": output_path})
        result = await self._run_historical_shadow_replay_job(product_id=product_id, timeframe=timeframe, write_mode="worker_file", output_path=output_path)
        updates = {"finished_ts": now_ts(), "rows_written": int(result.get("rows_written", 0) or 0), "evaluated": int(result.get("evaluated", 0) or 0), "candle_rows": int(result.get("candles", 0) or 0), "source": str(result.get("source") or ""), "output_path": output_path}
        if bool(result.get("ok")):
            updates["status"] = JOB_DONE
            updates["error"] = ""
        else:
            updates["status"] = JOB_FAILED
            updates["error"] = str(result.get("error") or "worker job failed")
        async with self._historical_replay_manifest_lock:
            update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates=updates)
        return result


    def _ensure_csv_header(self, path: str, columns: List[str]) -> None:
        if os.path.exists(path) and os.path.getsize(path) > 0:
            return
        with open(path, "w", newline="", encoding="utf-8") as f:
            csv.writer(f).writerow(columns)

    def _ensure_agent_component_replay_attribution_header(self) -> None:
        self._ensure_csv_header(AGENT_COMPONENT_REPLAY_ATTRIBUTION_CSV_PATH, AGENT_COMPONENT_REPLAY_ATTRIBUTION_COLUMNS)

    def _ensure_agent_trade_policy_header(self) -> None:
        self._ensure_csv_header(AGENT_TRADE_POLICY_CSV_PATH, AGENT_TRADE_POLICY_COLUMNS)

    def _write_agent_component_replay_attribution(self) -> None:
        try:
            self._ensure_agent_component_replay_attribution_header()
            frame = self._read_csv_tail_for_bot(HISTORICAL_SHADOW_REPLAY_CSV_PATH, max_lines=750000)
            if frame.empty: return
            component_map = {"volume_profile_leader_buy_score": "volume_profile_leader", "price_action_buy_score": "price_action", "market_structure_buy_score": "market_structure", "quant_buy_score": "quant_context"}
            rows = []
            for score_col, component in component_map.items():
                if score_col not in frame.columns: continue
                df = frame.copy(); df[score_col] = pd.to_numeric(df[score_col], errors="coerce")
                df["coinbase_mm"] = pd.to_numeric(df.get("coinbase_maker_maker_net_pnl_bps"), errors="coerce"); df["binance_mm"] = pd.to_numeric(df.get("binance_maker_maker_net_pnl_bps"), errors="coerce")
                valid = df.dropna(subset=[score_col, "coinbase_mm", "binance_mm"])
                if valid.empty: continue
                threshold = float(valid[score_col].quantile(0.70)); high = valid[valid[score_col] >= threshold]; low = valid[valid[score_col] < threshold]
                if high.empty or low.empty: continue
                high_cb = float(high["coinbase_mm"].mean()); low_cb = float(low["coinbase_mm"].mean()); high_bn = float(high["binance_mm"].mean()); low_bn = float(low["binance_mm"].mean())
                high_stop = float(high["exit_reason"].astype(str).eq("historical_hard_stop").mean()) if "exit_reason" in high.columns else 0.0; low_stop = float(low["exit_reason"].astype(str).eq("historical_hard_stop").mean()) if "exit_reason" in low.columns else 0.0
                edge_cb = high_cb - low_cb; edge_bn = high_bn - low_bn
                role = "entry_confirmer" if (edge_cb > 10 or edge_bn > 10) else "risk_filter" if (high_stop < low_stop and (edge_cb > 0 or edge_bn > 0)) else "veto_or_low_value"
                rows.append({"ts": now_ts(), "dt_mst": datetime.fromtimestamp(now_ts(), tz=timezone.utc).astimezone(TZ).strftime("%Y-%m-%d %H:%M:%S"), "component": component, "rows": int(len(valid)), "high_score_rows": int(len(high)), "low_score_rows": int(len(low)), "high_score_avg_coinbase_maker_maker_bps": high_cb, "low_score_avg_coinbase_maker_maker_bps": low_cb, "high_score_avg_binance_maker_maker_bps": high_bn, "low_score_avg_binance_maker_maker_bps": low_bn, "high_score_hard_stop_rate": high_stop, "low_score_hard_stop_rate": low_stop, "edge_vs_low_coinbase_bps": edge_cb, "edge_vs_low_binance_bps": edge_bn, "recommended_role": role, "reason": f"component_attribution;score_col={score_col};threshold={threshold:.4f}"})
            if rows:
                with open(AGENT_COMPONENT_REPLAY_ATTRIBUTION_CSV_PATH, "a", newline="", encoding="utf-8") as f:
                    writer = csv.DictWriter(f, fieldnames=AGENT_COMPONENT_REPLAY_ATTRIBUTION_COLUMNS); [writer.writerow({col: row.get(col, "") for col in AGENT_COMPONENT_REPLAY_ATTRIBUTION_COLUMNS}) for row in rows]
        except Exception as exc:
            module_exception(MODULE_NAME, "write_agent_component_replay_attribution_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=False)

    def _write_agent_trade_policy(self) -> None:
        try:
            self._ensure_agent_trade_policy_header(); frame = self._read_csv_tail_for_bot(AGENT_PERFORMANCE_CSV_PATH, max_lines=200000)
            if frame.empty or "agent" not in frame.columns: return
            frame["move"] = pd.to_numeric(frame.get("outcome_move_bps"), errors="coerce"); frame["weighted_credit"] = pd.to_numeric(frame.get("weighted_agent_credit_score"), errors="coerce"); frame["success"] = pd.to_numeric(frame.get("outcome_success"), errors="coerce")
            rows = []
            for agent, group in frame.groupby(frame["agent"].astype(str)):
                direction = group.get("agent_direction", pd.Series(dtype=str)).astype(str).str.upper(); buy = group[direction.eq("BUY")]; wait_hold = group[direction.isin(["WAIT", "HOLD"])]
                buy_rows = int(len(buy)); wait_rows = int(len(wait_hold)); buy_avg = float(buy["move"].mean()) if buy_rows else 0.0; buy_success = float(buy["success"].mean()) if buy_rows else 0.0; wait_avg = float(wait_hold["move"].mean()) if wait_rows else 0.0; wait_success = float(wait_hold["success"].mean()) if wait_rows else 0.0; avg_credit = float(group["weighted_credit"].mean()) if "weighted_credit" in group.columns else 0.0
                if buy_rows >= 10 and buy_avg > 1.5 and buy_success >= 0.55: role, entry_mult, veto_mult = "entry_confirmer", 1.25, 1.0
                elif buy_rows >= 10 and buy_avg < -2.0: role, entry_mult, veto_mult = "buy_signal_penalty_veto_filter", 0.70, 1.25
                elif wait_rows >= 20 and wait_success >= 0.88: role, entry_mult, veto_mult = "avoidance_veto_filter", 0.85, 1.20
                else: role, entry_mult, veto_mult = "neutral", 1.0, 1.0
                rows.append({"ts": now_ts(), "dt_mst": datetime.fromtimestamp(now_ts(), tz=timezone.utc).astimezone(TZ).strftime("%Y-%m-%d %H:%M:%S"), "agent": agent, "rows": int(len(group)), "buy_rows": buy_rows, "buy_avg_move_bps": buy_avg, "buy_success_rate": buy_success, "wait_hold_rows": wait_rows, "wait_hold_avg_move_bps": wait_avg, "wait_hold_success_rate": wait_success, "avg_weighted_credit": avg_credit, "recommended_role": role, "entry_weight_multiplier": entry_mult, "veto_weight_multiplier": veto_mult, "reason": "runtime_agent_policy_from_observed_outcomes"})
            if rows:
                with open(AGENT_TRADE_POLICY_CSV_PATH, "a", newline="", encoding="utf-8") as f:
                    writer = csv.DictWriter(f, fieldnames=AGENT_TRADE_POLICY_COLUMNS); [writer.writerow({col: row.get(col, "") for col in AGENT_TRADE_POLICY_COLUMNS}) for row in rows]
        except Exception as exc:
            module_exception(MODULE_NAME, "write_agent_trade_policy_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=False)

    def _latest_agent_trade_policy(self) -> Dict[str, Dict[str, Any]]:
        try:
            frame = self._read_csv_tail_for_bot(AGENT_TRADE_POLICY_CSV_PATH, max_lines=5000)
            if frame.empty or "agent" not in frame.columns: return {}
            frame = frame.sort_values("ts").groupby("agent", as_index=False).tail(1); out = {}
            for _, r in frame.iterrows():
                agent = str(r.get("agent") or "")
                if agent: out[agent] = {"recommended_role": str(r.get("recommended_role") or "neutral"), "entry_weight_multiplier": float(r.get("entry_weight_multiplier", 1.0) or 1.0), "veto_weight_multiplier": float(r.get("veto_weight_multiplier", 1.0) or 1.0), "buy_avg_move_bps": float(r.get("buy_avg_move_bps", 0.0) or 0.0), "buy_success_rate": float(r.get("buy_success_rate", 0.0) or 0.0)}
            return out
        except Exception: return {}

    def _latest_strategy_variant_policy(self) -> Dict[Tuple[str, str, str], Dict[str, Any]]:
        try:
            frame = self._read_csv_tail_for_bot(STRATEGY_VARIANT_REPLAY_SUMMARY_CSV_PATH, max_lines=10000)
            if frame.empty: return {}
            frame = frame.sort_values("ts").groupby(["product_id", "timeframe", "strategy_variant"], as_index=False).tail(1); out = {}
            for _, r in frame.iterrows():
                key = (str(r.get("product_id") or ""), str(r.get("timeframe") or ""), str(r.get("strategy_variant") or "baseline"))
                out[key] = {"rows": int(r.get("rows", 0) or 0), "coinbase_mm_avg": float(r.get("coinbase_maker_maker_avg_bps", 0.0) or 0.0), "coinbase_mm_win": float(r.get("coinbase_maker_maker_win_rate", 0.0) or 0.0), "binance_mm_avg": float(r.get("binance_maker_maker_avg_bps", 0.0) or 0.0), "binance_mm_win": float(r.get("binance_maker_maker_win_rate", 0.0) or 0.0), "hard_stop_rate": float(r.get("hard_stop_rate", 1.0) or 1.0), "profit_pullback_rate": float(r.get("profit_pullback_rate", 0.0) or 0.0)}
            return out
        except Exception: return {}

    def _write_backtest_setup_performance_from_replay(self) -> None:
        try:
            self._ensure_csv_header(BACKTEST_SETUP_PERFORMANCE_CSV_PATH, BACKTEST_SETUP_PERFORMANCE_COLUMNS); frame = self._read_csv_tail_for_bot(HISTORICAL_SHADOW_REPLAY_CSV_PATH, max_lines=750000)
            if frame.empty: return
            for col in ["product_id", "timeframe", "setup_tag", "regime_tag", "strategy_variant"]:
                if col not in frame.columns: frame[col] = ""
            scenario = "coinbase_maker_maker_net_pnl_bps" if "coinbase_maker_maker_net_pnl_bps" in frame.columns else "net_pnl_bps"; frame[scenario] = pd.to_numeric(frame[scenario], errors="coerce"); rows=[]
            for keys, group in frame.groupby(["product_id", "timeframe", "strategy_variant", "setup_tag", "regime_tag"]):
                if len(group) < 10: continue
                pnl = group[scenario].dropna()
                if pnl.empty: continue
                rows.append({"ts": now_ts(), "dt_mst": datetime.fromtimestamp(now_ts(), tz=timezone.utc).astimezone(TZ).strftime("%Y-%m-%d %H:%M:%S"), "product_id": keys[0], "timeframe": keys[1], "strategy": keys[2], "setup_tag": keys[3], "market_regime": keys[4], "rows": int(len(group)), "win_rate": float((pnl > 0).mean()), "avg_move_bps": float(pnl.mean()), "median_move_bps": float(pnl.median()), "confidence": min(1.0, len(group) / 100.0), "recommended_action": "allow" if float(pnl.mean()) > 0 and float((pnl > 0).mean()) > 0.50 else "block", "reason": "historical_replay_setup_performance"})
            if rows:
                with open(BACKTEST_SETUP_PERFORMANCE_CSV_PATH, "a", newline="", encoding="utf-8") as f:
                    writer=csv.DictWriter(f, fieldnames=BACKTEST_SETUP_PERFORMANCE_COLUMNS); [writer.writerow({col: row.get(col, "") for col in BACKTEST_SETUP_PERFORMANCE_COLUMNS}) for row in rows]
        except Exception as exc: module_exception(MODULE_NAME, "write_backtest_setup_performance_from_replay_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=False)

    def _write_agent_ablation_from_component_attribution(self) -> None:
        try:
            self._ensure_csv_header(AGENT_ABLATION_CSV_PATH, AGENT_ABLATION_COLUMNS); frame = self._read_csv_tail_for_bot(AGENT_COMPONENT_REPLAY_ATTRIBUTION_CSV_PATH, max_lines=5000)
            if frame.empty: return
            rows=[]
            for _, r in frame.iterrows():
                edge_cb=float(pd.to_numeric(pd.Series([r.get("edge_vs_low_coinbase_bps")]), errors="coerce").fillna(0).iloc[0]); edge_bn=float(pd.to_numeric(pd.Series([r.get("edge_vs_low_binance_bps")]), errors="coerce").fillna(0).iloc[0])
                rows.append({"ts": now_ts(), "dt_mst": datetime.fromtimestamp(now_ts(), tz=timezone.utc).astimezone(TZ).strftime("%Y-%m-%d %H:%M:%S"), "agent": str(r.get("component") or ""), "rows": int(r.get("rows", 0) or 0), "with_agent_avg_bps": float(r.get("high_score_avg_coinbase_maker_maker_bps", 0.0) or 0.0), "without_agent_avg_bps": float(r.get("low_score_avg_coinbase_maker_maker_bps", 0.0) or 0.0), "delta_bps": edge_cb, "binance_delta_bps": edge_bn, "recommended_weight_adjustment": "increase" if edge_cb > 5 or edge_bn > 5 else "decrease" if edge_cb < -5 and edge_bn < -5 else "neutral", "reason": "component_replay_ablation_proxy"})
            if rows:
                with open(AGENT_ABLATION_CSV_PATH, "a", newline="", encoding="utf-8") as f:
                    writer=csv.DictWriter(f, fieldnames=AGENT_ABLATION_COLUMNS); [writer.writerow({col: row.get(col, "") for col in AGENT_ABLATION_COLUMNS}) for row in rows]
        except Exception as exc: module_exception(MODULE_NAME, "write_agent_ablation_from_component_attribution_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=False)
    async def _merge_completed_worker_outputs(self) -> Dict[str, Any]:
        if not bool(ENABLE_HISTORICAL_REPLAY_WORKER_ARCHITECTURE):
            return {"merged_jobs": 0, "rows_appended": 0}
        async with self._historical_replay_merge_lock:
            manifest = self._load_historical_replay_manifest()
            done_jobs = jobs_by_status(manifest, (JOB_DONE,))
            if not done_jobs:
                return {"merged_jobs": 0, "rows_appended": 0}
            master_keys = self._historical_master_replay_keys()
            rows_appended_total = 0
            merged_jobs = 0
            failed_merges = 0
            self._ensure_historical_shadow_replay_header()
            for job in done_jobs:
                job_id = str(job.get("job_id") or "")
                output_path = str(job.get("output_path") or "")
                rows = await asyncio.to_thread(self._read_worker_output_rows, output_path)
                if not rows:
                    async with self._historical_replay_manifest_lock:
                        update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates={"status": JOB_FAILED, "error": "worker output missing or empty"})
                    failed_merges += 1
                    continue
                new_rows = []
                for row in rows:
                    key = str(row.get("replay_key") or "")
                    if not key or key in master_keys:
                        continue
                    new_rows.append(row)
                    master_keys.add(key)
                if new_rows:
                    async with self._historical_replay_output_write_lock:
                        with open(HISTORICAL_SHADOW_REPLAY_CSV_PATH, "a", newline="", encoding="utf-8") as f:
                            writer = csv.DictWriter(f, fieldnames=HISTORICAL_SHADOW_REPLAY_COLUMNS)
                            for row in new_rows:
                                writer.writerow({col: row.get(col, "") for col in HISTORICAL_SHADOW_REPLAY_COLUMNS})
                async with self._historical_replay_manifest_lock:
                    update_job(path=HISTORICAL_REPLAY_MANIFEST_JSON_PATH, job_id=job_id, updates={"status": JOB_MERGED, "merged_ts": now_ts(), "rows_written": int(len(rows)), "rows_appended_to_master": int(len(new_rows)), "merge_note": ("merged_with_new_rows" if new_rows else "merged_but_all_rows_already_existed")})
                try:
                    self._write_replay_fee_comparison_summary_for_product(product_id=str(job.get("product_id") or ""), timeframe=str(job.get("timeframe") or ""))
                except Exception:
                    pass
                try:
                    self._write_historical_replay_summary(str(job.get("product_id") or ""))
                except Exception:
                    pass
                try:
                    self._write_strategy_variant_replay_summary_for_product(product_id=str(job.get("product_id") or ""), timeframe=str(job.get("timeframe") or ""))
                except Exception:
                    pass
                try:
                    self._write_agent_component_replay_attribution()
                except Exception:
                    pass
                try:
                    self._write_agent_trade_policy()
                except Exception:
                    pass
                try:
                    self._write_backtest_setup_performance_from_replay()
                except Exception:
                    pass
                try:
                    self._write_agent_ablation_from_component_attribution()
                except Exception:
                    pass
                if self._historical_worker_pool is not None and process_worker_output_summary is not None:
                    try:
                        loop = asyncio.get_running_loop()
                        summary = await loop.run_in_executor(self._historical_worker_pool, process_worker_output_summary, {"product_id": str(job.get("product_id") or ""), "timeframe": str(job.get("timeframe") or ""), "output_path": output_path})
                        module_debug(MODULE_NAME, "historical_replay_worker_output_process_summary", data=summary, level="DEBUG", also_overall=False)
                    except Exception:
                        pass
                rows_appended_total += len(new_rows)
                merged_jobs += 1
            self._historical_replay_counts_cache_ts = 0.0
            self._historical_replay_existing_keys_cache_ts = 0.0
            self._calculation_status_cache_ts = 0.0
            result = {"merged_jobs": int(merged_jobs), "failed_merges": int(failed_merges), "rows_appended": int(rows_appended_total)}
            module_debug(MODULE_NAME, "historical_replay_worker_outputs_merged", data=result, level="INFO", also_overall=False)
            return result

    async def _run_manifest_worker_batch(self) -> Dict[str, Any]:
        if not bool(ENABLE_HISTORICAL_REPLAY_WORKER_ARCHITECTURE):
            return {"used_manifest_workers": False}
        jobs = self._next_manifest_jobs(int(HIST_REPLAY_STARTUP_PARALLEL_JOBS))
        if not jobs:
            merge_result = await self._merge_completed_worker_outputs()
            return {"used_manifest_workers": True, "jobs_started": 0, "merge_result": merge_result}
        module_debug(MODULE_NAME, "historical_replay_manifest_worker_batch_started", data={"jobs_started": len(jobs), "jobs": [{"job_id": j.get("job_id"), "product_id": j.get("product_id"), "timeframe": j.get("timeframe"), "attempts": j.get("attempts")} for j in jobs]}, level="INFO", also_overall=False)
        if (bool(ENABLE_FULL_REPLAY_MATH_IN_PROCESS_WORKERS) and self._historical_worker_pool is not None and run_full_replay_worker_job is not None):
            tasks = [asyncio.create_task(self._run_manifest_job_in_process_worker(job)) for job in jobs]
        else:
            tasks = [asyncio.create_task(self._run_manifest_job_to_worker_file(job)) for job in jobs]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        failures = 0
        clean_results = []
        for result in results:
            if isinstance(result, Exception):
                failures += 1
                clean_results.append({"ok": False, "error": str(result)})
            else:
                clean_results.append(result)
        merge_result = await self._merge_completed_worker_outputs()
        self._write_calculation_status(force=True)
        out = {"used_manifest_workers": True, "jobs_started": len(jobs), "failures": failures, "results": clean_results, "merge_result": merge_result}
        module_debug(MODULE_NAME, "historical_replay_manifest_worker_batch_completed", data=out, level="INFO", also_overall=False)
        return out

    async def _run_historical_shadow_replay_pass(self, *, force: bool = False) -> None:
        if not bool(ENABLE_HISTORICAL_SHADOW_REPLAY): return
        if bool(getattr(self, "_historical_replay_running", False)): return
        now_value = now_ts()
        if (not bool(force) and now_value - float(getattr(self, "_last_historical_replay_ts", 0.0) or 0.0) < float(HIST_REPLAY_EVERY_SEC)): return
        self._historical_replay_running = True
        self._last_historical_replay_ts = now_value
        pass_started = time.perf_counter()
        try:
            jobs = self._next_historical_replay_jobs(1)
            if not jobs:
                return
            product_id, timeframe = jobs[0]
            result = await self._run_historical_shadow_replay_job(product_id=product_id, timeframe=timeframe)
            self._write_calculation_status(force=True)
            self._compact_historical_replay_caches_if_due()
            module_debug(MODULE_NAME, "historical_shadow_replay_pass_completed", data={**result, "total_pass_elapsed_sec": round(time.perf_counter() - pass_started, 3), "next_job_index": self._historical_replay_job_index, "job_count": len(self._historical_replay_job_queue())}, level="INFO", also_overall=False)
        except Exception as exc:
            module_exception(MODULE_NAME, "historical_shadow_replay_pass_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=True)
        finally:
            self._historical_replay_running = False

    async def _run_historical_shadow_replay_parallel_batch(self, *, force: bool = False) -> None:
        if not bool(ENABLE_HISTORICAL_SHADOW_REPLAY): return
        if bool(getattr(self, "_historical_replay_batch_running", False)): return
        now_value = now_ts()
        if (not bool(force) and now_value - float(getattr(self, "_last_historical_replay_ts", 0.0) or 0.0) < float(HIST_REPLAY_EVERY_SEC)): return
        self._historical_replay_batch_running = True
        self._historical_replay_running = True
        self._last_historical_replay_ts = now_value
        batch_started = time.perf_counter()
        try:
            jobs = self._next_historical_replay_jobs(int(HIST_REPLAY_STARTUP_PARALLEL_JOBS))
            if not jobs:
                return
            module_debug(MODULE_NAME, "historical_shadow_replay_parallel_batch_started", data={"job_count": len(jobs), "jobs": [{"product_id": p, "timeframe": tf} for p, tf in jobs], "fetch_concurrency": int(HIST_REPLAY_MAX_PARALLEL_FETCHES)}, level="INFO", also_overall=False)
            tasks = [asyncio.create_task(self._run_historical_shadow_replay_job(product_id=product_id, timeframe=timeframe)) for product_id, timeframe in jobs]
            results = await asyncio.gather(*tasks, return_exceptions=True)
            clean_results = []
            rows_written_total = 0
            evaluated_total = 0
            failures = 0
            for result in results:
                if isinstance(result, Exception):
                    failures += 1
                    clean_results.append({"ok": False, "error": str(result)})
                    continue
                clean_results.append(result)
                rows_written_total += int(result.get("rows_written", 0) or 0)
                evaluated_total += int(result.get("evaluated", 0) or 0)
            if bool(ENABLE_HISTORICAL_REPLAY_WORKER_ARCHITECTURE):
                await self._merge_completed_worker_outputs()
            self._write_calculation_status(force=True)
            self._compact_historical_replay_caches_if_due()
            module_debug(MODULE_NAME, "historical_shadow_replay_parallel_batch_completed", data={"job_count": len(jobs), "rows_written_total": rows_written_total, "evaluated_total": evaluated_total, "failures": failures, "elapsed_sec": round(time.perf_counter() - batch_started, 3), "results": clean_results, "next_job_index": self._historical_replay_job_index}, level="INFO", also_overall=False)
        except Exception as exc:
            module_exception(MODULE_NAME, "historical_shadow_replay_parallel_batch_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=True)
        finally:
            self._historical_replay_batch_running = False
            self._historical_replay_running = False

    async def historical_shadow_replay_loop(self) -> None:
        await asyncio.sleep(10.0)
        await self._historical_replay_worker_pool_health_check()
        while not self._stop_event.is_set():
            try:
                calc_status = self._calculation_status(force=False)
                unlocked = bool(calc_status.get("full_viewer_unlocked"))
                if bool(HIST_REPLAY_STARTUP_ACCELERATION_ENABLED) and not unlocked:
                    module_debug(MODULE_NAME, "historical_replay_startup_acceleration_cycle", data={"parallel_enabled": bool(HIST_REPLAY_PARALLEL_STARTUP_ENABLED), "parallel_jobs": int(HIST_REPLAY_STARTUP_PARALLEL_JOBS), "fetch_concurrency": int(HIST_REPLAY_MAX_PARALLEL_FETCHES), "progress_pct": round(float(calc_status.get("overall_progress_pct", 0.0)), 2), "phase": calc_status.get("phase_label")}, level="INFO", also_overall=False)
                    if bool(ENABLE_HISTORICAL_REPLAY_WORKER_ARCHITECTURE):
                        await self._run_manifest_worker_batch()
                    elif bool(HIST_REPLAY_PARALLEL_STARTUP_ENABLED):
                        await self._run_historical_shadow_replay_parallel_batch(force=True)
                    else:
                        jobs_to_run = int(HIST_REPLAY_STARTUP_JOBS_PER_CYCLE)
                        for _ in range(max(1, jobs_to_run)):
                            if self._stop_event.is_set():
                                break
                            await self._run_historical_shadow_replay_pass(force=True)
                            await asyncio.sleep(float(HIST_REPLAY_STARTUP_SLEEP_SEC))
                    await asyncio.sleep(float(HIST_REPLAY_STARTUP_BATCH_SLEEP_SEC))
                else:
                    await self._run_historical_shadow_replay_pass(force=False)
                    await asyncio.sleep(float(HIST_REPLAY_NORMAL_SLEEP_SEC))
            except Exception as exc:
                module_exception(MODULE_NAME, "historical_shadow_replay_loop_failed", exc, data={"traceback": traceback.format_exc()}, also_overall=True)
                await asyncio.sleep(10.0)

    def _historical_replay_rows_for_product(self, product_id: str) -> pd.DataFrame:
        try:
            frame = self._read_csv_tail_for_bot(HISTORICAL_SHADOW_REPLAY_CSV_PATH, max_lines=150000)
            if frame.empty or "product_id" not in frame.columns: return pd.DataFrame()
            frame = frame[frame["product_id"].astype(str).eq(str(product_id))].copy()
            if frame.empty: return pd.DataFrame()
            for col in ["replay_ts", "net_pnl_bps", "score", "probability", "max_favorable_bps", "max_adverse_bps"]:
                if col in frame.columns: frame[col] = pd.to_numeric(frame.get(col), errors="coerce")
            frame = frame.dropna(subset=["replay_ts", "net_pnl_bps", "score", "probability"])
            if "accepted_for_calibration" in frame.columns:
                accepted = pd.to_numeric(frame.get("accepted_for_calibration"), errors="coerce").fillna(0)
                frame = frame[accepted.astype(int).eq(1)].copy()
            if "replay_candidate_qualified" in frame.columns:
                qualified = pd.to_numeric(frame.get("replay_candidate_qualified"), errors="coerce").fillna(0)
                frame = frame[qualified.astype(int).eq(1)].copy()
            return frame.sort_values("replay_ts")
        except Exception as exc:
            module_exception(MODULE_NAME, "historical_replay_rows_for_product_failed", exc, data={"product_id": product_id, "traceback": traceback.format_exc()}, also_overall=False); return pd.DataFrame()

    def _replay_support_for_live_candidate(self, product_id: str, candidate: Dict[str, Any]) -> Tuple[bool, str]:
        try:
            if not bool(ENABLE_REPLAY_SUPPORT_LIVE_BUY_GATE):
                return True, "replay_support_gate_disabled"
            frame = self._historical_replay_rows_for_product(product_id)
            if frame.empty:
                expected_utility = float(candidate.get("expected_utility_bps", 0.0) or 0.0)
                if bool(ALLOW_STRONG_UTILITY_OVERRIDE_WITHOUT_REPLAY) and expected_utility >= float(STRONG_UTILITY_OVERRIDE_MIN_BPS):
                    return True, f"strong_utility_override_no_replay expected_utility={expected_utility:.2f};min={float(STRONG_UTILITY_OVERRIDE_MIN_BPS):.2f}"
                return False, "no_qualified_historical_replay_rows"
            net = pd.to_numeric(frame.get("net_pnl_bps"), errors="coerce").dropna()
            if net.empty:
                return False, "qualified_replay_has_no_net_pnl"
            rows = int(len(net))
            avg_net = float(net.mean())
            win_rate = float((net > 0).mean())
            if rows < int(REPLAY_SUPPORT_MIN_ROWS):
                return False, f"not_enough_replay_rows rows={rows};min={int(REPLAY_SUPPORT_MIN_ROWS)}"
            if avg_net < float(REPLAY_SUPPORT_MIN_AVG_NET_BPS):
                return False, f"replay_avg_net_too_low avg_net={avg_net:.2f};min={float(REPLAY_SUPPORT_MIN_AVG_NET_BPS):.2f}"
            if win_rate < float(REPLAY_SUPPORT_MIN_WIN_RATE):
                return False, f"replay_win_rate_too_low win_rate={win_rate:.3f};min={float(REPLAY_SUPPORT_MIN_WIN_RATE):.3f}"
            return True, f"replay_supported rows={rows};avg_net={avg_net:.2f};win_rate={win_rate:.3f}"
        except Exception as exc:
            module_exception(MODULE_NAME, "replay_support_for_live_candidate_failed", exc, data={"product_id": product_id, "traceback": traceback.format_exc()}, also_overall=False)
            return False, "replay_support_check_failed"

    def _all_historical_replay_rows_for_product(self, product_id: str) -> pd.DataFrame:
        try:
            frame = self._read_csv_tail_for_bot(HISTORICAL_SHADOW_REPLAY_CSV_PATH, max_lines=150000)
            if frame.empty or "product_id" not in frame.columns:
                return pd.DataFrame()
            frame = frame[frame["product_id"].astype(str).eq(str(product_id))].copy()
            for col in ["replay_ts", "net_pnl_bps", "score", "probability", "max_favorable_bps", "max_adverse_bps"]:
                if col in frame.columns:
                    frame[col] = pd.to_numeric(frame.get(col), errors="coerce")
            return frame.sort_values("replay_ts") if "replay_ts" in frame.columns else frame
        except Exception as exc:
            module_exception(MODULE_NAME, "all_historical_replay_rows_for_product_failed", exc, data={"product_id": product_id, "traceback": traceback.format_exc()}, also_overall=False)
            return pd.DataFrame()

    def _count_rows_by_product_from_csv(self, path: str, *, max_lines: int = 200000) -> Dict[str, int]:
        counts = {p: 0 for p in PRODUCTS}
        try:
            frame = self._read_csv_tail_for_bot(path, max_lines=max_lines)
            if frame.empty or "product_id" not in frame.columns:
                return counts
            vc = frame["product_id"].astype(str).value_counts().to_dict()
            for product_id in PRODUCTS:
                counts[product_id] = int(vc.get(product_id, 0))
            return counts
        except Exception as exc:
            module_exception(MODULE_NAME, "count_rows_by_product_from_csv_failed", exc, data={"path": path, "traceback": traceback.format_exc()}, also_overall=False)
            return counts

    def _historical_replay_counts_for_product(self, product_id: str) -> Dict[str, Any]:
        counts = {"all_rows": 0, "primary_15m_90d_rows": 0, "regime_1h_365d_rows": 0, "daily_1d_2y_rows": 0, "qualified_rows": 0, "accepted_rows": 0, "wins": 0, "losses": 0, "avg_net_pnl_bps": 0.0, "median_net_pnl_bps": 0.0, "win_rate": 0.0}
        try:
            frame = self._all_historical_replay_rows_for_product(product_id)
            if frame.empty:
                return counts
            counts["all_rows"] = int(len(frame))
            if "timeframe" in frame.columns:
                tf = frame["timeframe"].astype(str)
                counts["primary_15m_90d_rows"] = int(tf.eq("primary_15m_90d").sum())
                counts["regime_1h_365d_rows"] = int(tf.eq("regime_1h_365d").sum())
                counts["daily_1d_2y_rows"] = int(tf.eq("daily_1d_2y").sum())
            if "replay_candidate_qualified" in frame.columns:
                qualified = pd.to_numeric(frame.get("replay_candidate_qualified"), errors="coerce").fillna(0)
                counts["qualified_rows"] = int(qualified.astype(int).eq(1).sum())
            if "accepted_for_calibration" in frame.columns:
                accepted = pd.to_numeric(frame.get("accepted_for_calibration"), errors="coerce").fillna(0)
                counts["accepted_rows"] = int(accepted.astype(int).eq(1).sum())
            net = pd.to_numeric(frame.get("net_pnl_bps"), errors="coerce").dropna()
            if not net.empty:
                counts["wins"] = int((net > 0).sum())
                counts["losses"] = int((net <= 0).sum())
                counts["avg_net_pnl_bps"] = float(net.mean())
                counts["median_net_pnl_bps"] = float(net.median())
                counts["win_rate"] = float((net > 0).mean())
            return counts
        except Exception as exc:
            module_exception(MODULE_NAME, "historical_replay_counts_for_product_failed", exc, data={"product_id": product_id, "traceback": traceback.format_exc()}, also_overall=False)
            return counts

    def _historical_profit_verdict_for_product(self, product_id: str) -> Dict[str, Any]:
        counts = self._historical_replay_counts_for_product(product_id)
        has_required_15m = counts["primary_15m_90d_rows"] >= int(STARTUP_CALC_REQUIRED_15M_REPLAY_ROWS_PER_PRODUCT)
        has_required_1h = counts["regime_1h_365d_rows"] >= int(STARTUP_CALC_REQUIRED_1H_REPLAY_ROWS_PER_PRODUCT)
        replay_complete = bool(has_required_15m and has_required_1h)
        qualified_rows = int(counts["qualified_rows"]); accepted_rows = int(counts["accepted_rows"]); wins = int(counts["wins"])
        avg_net = float(counts["avg_net_pnl_bps"]); median_net = float(counts["median_net_pnl_bps"]); win_rate = float(counts["win_rate"])
        profit_ready = bool(replay_complete and accepted_rows >= int(HIST_REPLAY_MIN_ROWS_FOR_PRODUCT_CALIBRATION) and wins >= int(HIST_REPLAY_MIN_WINS_FOR_PRODUCT_CALIBRATION) and avg_net >= float(HIST_REPLAY_MIN_AVG_NET_PNL_BPS_FOR_CALIBRATION))
        if profit_ready:
            verdict = "profit_replay_ready"; complete = True; live_trade_allowed = True
            reason = f"profit replay ready; accepted_rows={accepted_rows};wins={wins};avg_net={avg_net:.2f};median_net={median_net:.2f};win_rate={win_rate:.3f}"
        elif replay_complete and bool(STARTUP_CALC_ACCEPT_UNPROFITABLE_VERDICT_AS_COMPLETE):
            verdict = "replay_complete_unprofitable_or_unqualified"; complete = True; live_trade_allowed = False
            reason = f"replay complete but not profitable enough; qualified_rows={qualified_rows};accepted_rows={accepted_rows};wins={wins};avg_net={avg_net:.2f};median_net={median_net:.2f};win_rate={win_rate:.3f}"
        else:
            verdict = "replay_incomplete"; complete = False; live_trade_allowed = False
